begin;
create table if not exists public.authorized_users(user_id uuid primary key references auth.users(id) on delete cascade, enabled boolean not null default true);
alter table public.authorized_users enable row level security;
create or replace function public.cte_allowed() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.authorized_users where user_id=(select auth.uid()) and enabled)$$;
revoke all on function public.cte_allowed() from public;
grant execute on function public.cte_allowed() to authenticated;
drop policy if exists self_membership on public.authorized_users;
create policy self_membership on public.authorized_users for select to authenticated using (user_id=(select auth.uid()));
grant select on public.authorized_users to authenticated;
revoke insert,update,delete on public.authorized_users from anon,authenticated;
create table if not exists public.documents(id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,environment text not null check(environment in ('test','production')),created timestamptz not null default now(),data jsonb not null,xml_key text,access_key text check(access_key is null or access_key ~ '^[0-9]{44}$'),unique(owner_id,access_key));
create index if not exists documents_owner_created on public.documents(owner_id,created desc);
create table if not exists public.settings(owner_id uuid not null references auth.users(id) on delete cascade,id text not null,data jsonb not null,primary key(owner_id,id));
alter table public.documents enable row level security;
alter table public.settings enable row level security;
revoke all on public.documents,public.settings from anon;
grant select,insert,update,delete on public.documents,public.settings to authenticated;
drop policy if exists own_documents on public.documents;
create policy own_documents on public.documents for all to authenticated using(owner_id=(select auth.uid()) and public.cte_allowed()) with check(owner_id=(select auth.uid()) and public.cte_allowed());
drop policy if exists own_settings on public.settings;
create policy own_settings on public.settings for all to authenticated using(owner_id=(select auth.uid()) and public.cte_allowed()) with check(owner_id=(select auth.uid()) and public.cte_allowed());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('cte-xml','cte-xml',false,2000000,array['application/xml','text/xml']) on conflict(id) do update set public=false,file_size_limit=2000000,allowed_mime_types=array['application/xml','text/xml'];
drop policy if exists own_cte_xml_select on storage.objects;
create policy own_cte_xml_select on storage.objects for select to authenticated using(bucket_id='cte-xml' and (storage.foldername(name))[1]=(select auth.uid())::text and public.cte_allowed());
drop policy if exists own_cte_xml_insert on storage.objects;
create policy own_cte_xml_insert on storage.objects for insert to authenticated with check(bucket_id='cte-xml' and (storage.foldername(name))[1]=(select auth.uid())::text and public.cte_allowed());
drop policy if exists own_cte_xml_delete on storage.objects;
create policy own_cte_xml_delete on storage.objects for delete to authenticated using(bucket_id='cte-xml' and (storage.foldername(name))[1]=(select auth.uid())::text and public.cte_allowed());
commit;
